package library;

import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.LocalDate;
import java.util.*;
import java.util.regex.*;

/** Dependency-free Java HTTP backend for the Digital Library application. */
public class LibraryServer {
    private final BookStore store=new BookStore(); private final UserStore userStore; private final LoanStore loanStore=new LoanStore();
    private final Map<String,Book> books=new LinkedHashMap<>(); private final CatalogIndex index=new CatalogIndex();
    private final List<Loan> loans=new ArrayList<>();
    private final Map<String,String> sessions=new java.util.concurrent.ConcurrentHashMap<>();
    private LibraryServer() throws Exception { userStore=new UserStore();for(Book b:store.load())books.put(b.isbn(),b);loans.addAll(loanStore.load());rebuild(); }
    private synchronized List<Book> all(){return new ArrayList<>(books.values());}
    private synchronized List<Loan> allLoans(){return new ArrayList<>(loans);}
    private synchronized boolean isAvailable(String isbn){return loans.stream().noneMatch(l->l.active()&&l.isbn().equals(isbn));}
    private synchronized void rebuild(){index.rebuild(books.values());}
    public static void main(String[] args)throws Exception {
        int port=args.length==0?8080:Integer.parseInt(args[0]); LibraryServer app=new LibraryServer();
        HttpServer server=HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(),port),0);server.createContext("/api/",app::api);server.createContext("/",app::staticFile);server.setExecutor(java.util.concurrent.Executors.newCachedThreadPool());
        Runtime.getRuntime().addShutdownHook(new Thread(()->server.stop(1)));server.start();System.out.println("Digital Library running at http://localhost:"+port);
        if(app.userStore.bootstrapAdminPassword()!=null){System.out.println("First-run admin account: "+UserStore.ADMIN_EMAIL);System.out.println("One-time admin password (save it now): "+app.userStore.bootstrapAdminPassword());}
    }
    private void api(HttpExchange x)throws IOException {
        x.getResponseHeaders().set("Access-Control-Allow-Origin","*");x.getResponseHeaders().set("Access-Control-Allow-Headers","Content-Type");x.getResponseHeaders().set("Access-Control-Allow-Methods","GET,POST,PUT,DELETE,OPTIONS");
        if(x.getRequestMethod().equals("OPTIONS")){send(x,204,"");return;}
        try {String path=x.getRequestURI().getPath(), method=x.getRequestMethod();Map<String,String> query=query(x.getRequestURI().getRawQuery());
            if(path.equals("/api/auth/register")&&method.equals("POST")){Map<String,String>d=fields(body(x));LibraryUser user=userStore.register(d.get("name"),d.get("email"),d.get("password"),d.get("role"));sendSession(x,user,201);return;}
            if(path.equals("/api/auth/login")&&method.equals("POST")){Map<String,String>d=fields(body(x));LibraryUser user=userStore.authenticate(d.get("email"),d.get("password"));String selected=d.getOrDefault("role","READER").toUpperCase(Locale.ROOT);if(user==null){send(x,401,error("Email or password is incorrect"));return;}if(!user.role().equals(selected)){send(x,403,error("Choose the correct sign-in option for this account"));return;}sendSession(x,user,200);return;}
            if(path.equals("/api/auth/logout")&&method.equals("POST")){String token=sessionToken(x);if(token!=null)sessions.remove(token);x.getResponseHeaders().add("Set-Cookie","openshelf_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0");send(x,200,"{\"ok\":true}");return;}
            if(path.equals("/api/auth/me")&&method.equals("GET")){LibraryUser user=currentUser(x);send(x,200,user==null?"{\"signedIn\":false}":"{\"signedIn\":true,\"user\":"+user.publicJson()+"}");return;}
            if(path.equals("/api/preferences")&&method.equals("PUT")){LibraryUser user=currentUser(x);if(user==null){send(x,401,error("Sign in to save your preferences"));return;}Map<String,String>d=fields(body(x));LibraryUser saved=userStore.savePreferences(user.email(),lines(d.get("genres")),lines(d.get("authors")));send(x,200,saved.publicJson());return;}
            if(path.equals("/api/books")&&method.equals("GET")){String q=query.getOrDefault("q","").toLowerCase(Locale.ROOT);List<Book> result=all().stream().filter(b->q.isBlank()||String.join(" ",b.isbn(),b.title(),b.author(),b.genre(),b.location()).toLowerCase(Locale.ROOT).contains(q)).toList();send(x,200,catalogJson(result));return;}
            if(path.equals("/api/books")&&method.equals("POST")){if(requireAdmin(x)==null)return;Map<String,String> d=fields(body(x));Book b=new Book(d.get("isbn"),d.get("title"),d.get("author"),d.get("genre"),Double.parseDouble(d.getOrDefault("rating","0")),d.getOrDefault("description",""),Integer.parseInt(d.getOrDefault("year","0")),d.get("location"));synchronized(this){if(books.containsKey(b.isbn()))throw new IllegalArgumentException("That ISBN already exists");books.put(b.isbn(),b);store.save(books.values());rebuild();}send(x,201,b.json());return;}
            if(path.startsWith("/api/books/")&&method.equals("DELETE")){if(requireAdmin(x)==null)return;String isbn=URLDecoder.decode(path.substring("/api/books/".length()),StandardCharsets.UTF_8);synchronized(this){if(!books.containsKey(isbn)){send(x,404,error("Book not found"));return;}if(loans.stream().anyMatch(l->l.active()&&l.isbn().equals(isbn))){send(x,409,error("This book is currently borrowed and cannot be removed"));return;}books.remove(isbn);store.save(books.values());rebuild();}send(x,200,"{\"ok\":true}");return;}
            if(path.equals("/api/loans")&&method.equals("GET")){LibraryUser user=currentUser(x);if(user==null){send(x,401,error("Sign in to view borrowing records"));return;}List<Loan> visible=allLoans().stream().filter(l->user.role().equals("ADMIN")||l.userEmail().equals(user.email())).toList();send(x,200,"["+String.join(",",visible.stream().map(Loan::json).toList())+"]");return;}
            if(path.equals("/api/loans")&&method.equals("POST")){LibraryUser user=currentUser(x);if(user==null){send(x,401,error("Sign in to borrow a book"));return;}Map<String,String>d=fields(body(x));String isbn=d.getOrDefault("isbn","");synchronized(this){Book book=books.get(isbn);if(book==null){send(x,404,error("Book not found"));return;}if(!isAvailable(isbn)){send(x,409,error("This book is already borrowed"));return;}LocalDate today=LocalDate.now();Loan loan=new Loan(UUID.randomUUID().toString(),isbn,book.title(),user.email(),user.name(),today.toString(),today.plusDays(14).toString(),"");loans.add(loan);loanStore.save(loans);send(x,201,loan.json());}return;}
            if(path.startsWith("/api/loans/")&&path.endsWith("/return")&&method.equals("POST")){LibraryUser user=currentUser(x);if(user==null){send(x,401,error("Sign in as an admin to process a return"));return;}if(!user.role().equals("ADMIN")){send(x,403,error("Only admins can mark books as returned"));return;}String id=URLDecoder.decode(path.substring("/api/loans/".length(),path.length()-"/return".length()),StandardCharsets.UTF_8);synchronized(this){int i=-1;for(int n=0;n<loans.size();n++)if(loans.get(n).id().equals(id)){i=n;break;}if(i<0){send(x,404,error("Borrowing record not found"));return;}Loan loan=loans.get(i);if(!loan.active()){send(x,409,error("This book has already been returned"));return;}Loan returned=loan.returned(LocalDate.now().toString());loans.set(i,returned);loanStore.save(loans);send(x,200,returned.json());}return;}
            if(path.equals("/api/recommendations")){int k=Math.max(1,Math.min(20,Integer.parseInt(query.getOrDefault("k","5"))));LibraryUser user=currentUser(x);if(user!=null)send(x,200,json(recommendationJson(RecommendationEngine.personalized(all(),k,user))));else send(x,200,catalogJson(RecommendationEngine.topK(all(),k,query.getOrDefault("genre",""))));return;}
            if(path.equals("/api/graph")){List<Book> catalog=all();if(catalog.isEmpty()){send(x,200,"{}");return;}String start=query.getOrDefault("isbn",catalog.get(0).isbn());BookGraph g=new BookGraph(catalog);Map<String,Object> out=new LinkedHashMap<>();out.put("start",start);out.put("bfs",g.bfs(start));out.put("dfs",g.dfs(start));out.put("shortest",g.shortest(start).stream().map(e->Map.of("isbn",e.to(),"distance",e.weight())).toList());out.put("mst",g.prim().stream().map(e->Map.of("from",e.from(),"to",e.to(),"weight",e.weight())).toList());send(x,200,json(out));return;}
            if(path.equals("/api/stats")){List<Book> list=all();Map<String,Object>s=new LinkedHashMap<>();s.put("count",list.size());s.put("genres",list.stream().map(Book::genre).distinct().count());s.put("avlHeight",index.avlHeight());s.put("bstHeight",index.bstHeight());s.put("storage","data/books.tsv");send(x,200,json(s));return;}
            if(path.equals("/api/compress")){Book b=index.find(query.getOrDefault("isbn",""));if(b==null){send(x,404,error("Book not found"));return;}send(x,200,json(HuffmanCoder.measure(b.description())));return;}
            send(x,404,error("API route not found"));
        }catch(IllegalArgumentException e){send(x,400,error(e.getMessage()));}catch(Exception e){e.printStackTrace();send(x,500,error("Server error: "+e.getMessage()));}
    }
    private static String body(HttpExchange x)throws IOException{return new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);}
    private LibraryUser requireAdmin(HttpExchange x)throws IOException{LibraryUser user=currentUser(x);if(user==null){send(x,401,error("Sign in as an admin to manage books"));return null;}if(!user.role().equals("ADMIN")){send(x,403,error("Only admins can add or remove books"));return null;}return user;}
    private void sendSession(HttpExchange x,LibraryUser user,int status)throws IOException{String token=UUID.randomUUID().toString();sessions.put(token,user.email());x.getResponseHeaders().add("Set-Cookie","openshelf_session="+token+"; Path=/; HttpOnly; SameSite=Lax");send(x,status,"{\"signedIn\":true,\"user\":"+user.publicJson()+"}");}
    private LibraryUser currentUser(HttpExchange x){String token=sessionToken(x),email=token==null?null:sessions.get(token);return email==null?null:userStore.get(email);}
    private String sessionToken(HttpExchange x){String cookie=x.getRequestHeaders().getFirst("Cookie");if(cookie==null)return null;for(String part:cookie.split(";")){String[]kv=part.strip().split("=",2);if(kv.length==2&&kv[0].equals("openshelf_session"))return kv[1];}return null;}
    private static Set<String> lines(String value){if(value==null||value.isBlank())return Set.of();Set<String>out=new LinkedHashSet<>();for(String item:value.split("\\n"))if(!item.isBlank())out.add(item.strip());return out;}
    private void staticFile(HttpExchange x)throws IOException {String p=x.getRequestURI().getPath();if(p.equals("/"))p="/index.html";String name=p.substring(1);if(name.contains("..")||name.contains("\\")){send(x,404,"Not found");return;}String type=name.endsWith(".css")?"text/css; charset=utf-8":name.endsWith(".js")?"text/javascript; charset=utf-8":"text/html; charset=utf-8";try(InputStream in=LibraryServer.class.getClassLoader().getResourceAsStream(name)){if(in==null){send(x,404,"Not found");return;}byte[]b=in.readAllBytes();x.getResponseHeaders().set("Content-Type",type);x.sendResponseHeaders(200,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}}
    private static Map<String,String> query(String raw){Map<String,String>m=new HashMap<>();if(raw!=null)for(String p:raw.split("&")){String[]a=p.split("=",2);m.put(URLDecoder.decode(a[0],StandardCharsets.UTF_8),a.length>1?URLDecoder.decode(a[1],StandardCharsets.UTF_8):"");}return m;}
    private static Map<String,String> fields(String body){Map<String,String>m=new HashMap<>();Matcher a=Pattern.compile("\"(\\w+)\"\\s*:\\s*(\"(?:\\\\.|[^\"\\\\])*\"|-?[0-9]+(?:\\.[0-9]+)?|true|false|null)").matcher(body);while(a.find()){String v=a.group(2);m.put(a.group(1),v.startsWith("\"")?unquote(v):v);}return m;}
    private static String unquote(String s){return s.substring(1,s.length()-1).replace("\\n","\n").replace("\\r","\r").replace("\\t","\t").replace("\\\"","\"").replace("\\\\","\\");}
    private String catalogJson(Collection<Book> books){List<Map<String,Object>> rows=new ArrayList<>();for(Book b:books){Map<String,Object>row=new LinkedHashMap<>();row.put("isbn",b.isbn());row.put("title",b.title());row.put("author",b.author());row.put("genre",b.genre());row.put("rating",b.rating());row.put("description",b.description());row.put("year",b.year());row.put("location",b.location());row.put("available",isAvailable(b.isbn()));rows.add(row);}return json(rows);}
    private List<Map<String,Object>> recommendationJson(List<Map<String,Object>> books){for(Map<String,Object>book:books)book.put("available",isAvailable(String.valueOf(book.get("isbn"))));return books;}
    private String array(Collection<Book>b){return "["+String.join(",",b.stream().map(Book::json).toList())+"]";}
    private static String error(String s){return "{\"error\":"+Book.q(s==null?"Invalid request":s)+"}";}
    private static String json(Object o){if(o==null)return "null";if(o instanceof String s)return Book.q(s);if(o instanceof Number||o instanceof Boolean)return o.toString();if(o instanceof Map<?,?>m){List<String>p=new ArrayList<>();m.forEach((k,v)->p.add(Book.q(k.toString())+":"+json(v)));return "{"+String.join(",",p)+"}";}if(o instanceof Collection<?>c){List<String>p=new ArrayList<>();for(Object v:c)p.add(json(v));return "["+String.join(",",p)+"]";}return Book.q(o.toString());}
    private static void send(HttpExchange x,int status,String body)throws IOException {byte[]b=body.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");if(status==204){x.sendResponseHeaders(status,-1);return;}x.sendResponseHeaders(status,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
}
